#!/bin/bash
mongosh <<EOF
use admin
db.auth("${MONGODB_ROOT_USER}", "${MONGODB_ROOT_PASSWORD}")
db.createUser({
  user: "${MONGODB_EXTRA_USERNAMES}",
  pwd: "${MONGODB_EXTRA_PASSWORDS}",
  roles: [
    { db: "${MONGODB_EXTRA_DATABASES}", role: "dbOwner" },
    { db: "${MONGODB_EXTRA_DATABASES}_stat", role: "dbOwner" }
  ]
})
EOF

set -e
{{- range $name, $cfg := $.Values.mcstats }}

# Create instance dirs
mkdir -p /config/{{ $name }}/

# Write config.json
cat <<EOF > /config/{{ $name }}/config.json
{{ $cfg | toJson }}
EOF
echo "Created /config/{{ $name }}/config.json"
{{- end }}
